// TestQAImage_E2EIndependentRederive is the QA-01 independent re-derivation of
// AC-1/AC-image/AC-softfail/AC-unicode. It builds the real server + 3 plugin
// subprocesses, scans a DIFFERENT image fixture library (module_id=image), polls
// to the ready drain terminal, and asserts the EXIF JPEG's sources.image-enricher
// matches the independent exiftool ORACLE field-by-field (plus HEIC, Cyrillic,
// no-EXIF clean success, corrupt-persisted, namespace isolation, and idempotent
// re-scan). One server, one scan, independent assertions.
func TestQAImage_E2EIndependentRederive(t *testing.T) {
	if testing.Short() {
		t.Skip("QA image integration test: skips under -short (builds binaries + subprocess)")
	}
	if _, err := exec.LookPath("exiftool"); err != nil {
		t.Skip("exiftool not on PATH — skipping QA-01 re-derivation (INV-skip-clean)")
	}

	tmp := t.TempDir()
	serverBin := buildBinary(t, tmp, "qa-img-server", "./cmd/mellifera")
	scannerBin := buildBinary(t, tmp, "qa-img-scanner", "./plugins/base-scanner")
	tvParserBin := buildBinary(t, tmp, "qa-img-tvparser", "./plugins/tv-parser")
	imageEnricherBin := buildBinary(t, tmp, "qa-img-enricher", "./plugins/image-enricher")
	fx := qaImgWriteFixtures(t)

	baseURL := startServer(t, serverBin, scannerBin, tvParserBin, imageEnricherBin, tmp, qaImgToken)
	client := &http.Client{Timeout: httpTimeout}
	libID := qaImgCreateLibrary(t, client, baseURL, qaImgToken, fx.root)

	res := scanLibrary(t, client, baseURL, qaImgToken, libID)
	// AC-image gating: only image fixtures discovered (the stray .mp4 is gated OUT).
	if res.Discovered != len(fx.rels) || res.Persisted != len(fx.rels) {
		t.Fatalf("QA AC-image: scan discovered=%d persisted=%d, want %d (image fixtures only; .mp4 gated out)",
			res.Discovered, res.Persisted, len(fx.rels))
	}
	if _, leak := indexByPath(t, listItems(t, client, baseURL, qaImgToken, libID))["trailer.mp4"]; leak {
		t.Fatalf("QA AC-image: trailer.mp4 was discovered by the image module (module-type gating failed)")
	}

	byRel := qaImgWaitForReady(t, client, baseURL, libID, fx.rels)

	t.Run("AC1_EXIF_oracle_rederive", func(t *testing.T) { qaAssertEXIFOracle(t, byRel, fx) })
	t.Run("AC_image_HEIC", func(t *testing.T) { qaAssertHEIC(t, byRel, fx) })
	t.Run("AC_unicode_cyrillic", func(t *testing.T) { qaAssertCyrillic(t, byRel) })
	t.Run("AC_softfail_noexif_clean", func(t *testing.T) { qaAssertNoEXIFClean(t, byRel) })
	t.Run("AC_softfail_corrupt_persisted", func(t *testing.T) { qaAssertCorruptPersisted(t, byRel) })
	t.Run("AC1_namespace_isolation", func(t *testing.T) { qaAssertNamespaceIsolation(t, byRel) })
	t.Run("AC1_idempotent_rescan", func(t *testing.T) {
		qaAssertIdempotentRescan(t, client, baseURL, libID, byRel)
	})
}

// TestQAImage_ExiftoolMissingSoftFail is the reviewer's INFO-2: the full
// exiftool-missing INTEGRATION simulation the coder phase deferred via t.Skip. It
// starts the server with a PATH that contains ffprobe/ffmpeg but NOT exiftool
// (symlinks into a temp dir), scans an image library, and asserts the
// missing-exiftool SOFT-FAIL contract: scan returns 200 (no aborted scan), items
// are listable (no panic), base dimensions survive (stdlib probeImage needs no
// exiftool), and sources.image-enricher is ABSENT (exiftool LookPath failed ->
// empty namespace -> no enrichment written). The missing-tool cooldown timing is
// non-deterministic, so the hard assertions are the soft-fail invariants, not the
// ready status (AC-softfail explicitly allows pending/enriched mid-cooldown).
func TestQAImage_ExiftoolMissingSoftFail(t *testing.T) {
	if testing.Short() {
		t.Skip("QA image integration test: skips under -short (builds binaries + subprocess)")
	}
	if _, err := exec.LookPath("exiftool"); err != nil {
		t.Skip("exiftool not on PATH — cannot prove the soft-fail fires correctly when present; skipping")
	}
	stripped := qaImgStrippedPath(t) // ffprobe/ffmpeg only, NO exiftool

	tmp := t.TempDir()
	serverBin := buildBinary(t, tmp, "qa-miss-server", "./cmd/mellifera")
	scannerBin := buildBinary(t, tmp, "qa-miss-scanner", "./plugins/base-scanner")
	tvParserBin := buildBinary(t, tmp, "qa-miss-tvparser", "./plugins/tv-parser")
	imageEnricherBin := buildBinary(t, tmp, "qa-miss-enricher", "./plugins/image-enricher")
	root := t.TempDir()
	qaImgEncode(t, filepath.Join(root, "DSC_0001.jpg"), qaImgEXIFW, qaImgEXIFH, "jpeg")
	qaImgEncode(t, filepath.Join(root, "plain.png"), qaImgPNGW, qaImgPNGH, "png")

	baseURL := qaImgStartServerStrippedPath(t, serverBin, scannerBin, tvParserBin, imageEnricherBin, tmp, qaImgToken, stripped)
	client := &http.Client{Timeout: httpTimeout}
	libID := qaImgCreateLibrary(t, client, baseURL, qaImgToken, root)

	// AC-softfail: the scan ALWAYS succeeds (one missing tool never aborts the library).
	res := scanLibrary(t, client, baseURL, qaImgToken, libID)
	if res.Discovered != 2 || res.Persisted != 2 {
		t.Fatalf("exiftool-missing: scan discovered=%d persisted=%d, want 2/2 (scan must succeed without exiftool)",
			res.Discovered, res.Persisted)
	}

	// Items remain listable; give the worker a short window to attempt + soft-fail.
	byRel := qaImgPollListable(t, client, baseURL, libID)
	for _, rel := range []string{"DSC_0001.jpg", "plain.png"} {
		it, ok := byRel[rel]
		if !ok {
			t.Fatalf("exiftool-missing: %q not persisted (scan must be listable without exiftool); have %v",
				rel, pathsOf(byRel))
		}
		doc := parseAsyncDoc(t, it.Document)
		// The soft-fail contract: NO sources.image-enricher namespace (exiftool missing
		// -> empty Convert metadata -> Merge writes nothing for this source).
		if ns, present := doc.Sources["image-enricher"]; present && len(ns) > 0 {
			t.Errorf("exiftool-missing: %q sources.image-enricher = %v, want absent/empty (LookPath soft-fail)", rel, ns)
		}
		// AC-softfail: base dimensions survive (stdlib probeImage needs no exiftool).
		if rel == "DSC_0001.jpg" && len(doc.Ffprobe) == 0 {
			t.Errorf("exiftool-missing: %q base ffprobe empty, want non-empty {width,height,format} (stdlib discovery is exiftool-independent)", rel)
		}
	}
}

// qaAssertEXIFOracle is the independent re-derivation: it reads the EXIF JPEG's
// tags via a SEPARATE exiftool call (the oracle), derives the expected
// sources.image-enricher content (applying the enricher's mapping rules
// independently), and asserts the e2e enricher output matches field-by-field. A
// hardcoded enricher (echoing "Apple"/"iPhone 15") would fail here because the
// fixture carries Canon/EOS R6.
func qaAssertEXIFOracle(t *testing.T, byRel map[string]itemDTO, fx qaImgFixtures) {
	t.Helper()
	const rel = "DSC_5082.jpg"
	it, ok := byRel[rel]
	if !ok {
		t.Fatalf("QA AC-1: %q not persisted; have %v", rel, pathsOf(byRel))
	}
	if it.Status != "ready" {
		t.Fatalf("QA AC-1: %q status = %q, want ready", rel, it.Status)
	}
	want, err := qaImgExifOracle(fx.exifJPG)
	if err != nil {
		t.Fatalf("QA AC-1: independent exiftool oracle failed: %v", err)
	}
	doc := parseAsyncDoc(t, it.Document)
	ns := doc.Sources["image-enricher"]
	if ns == nil {
		t.Fatalf("QA AC-1: %q sources.image-enricher missing", rel)
	}
	// gps fields use a tolerance; the others must match the oracle exactly.
	for _, field := range []string{"width", "height", "orientation", "gps_lat", "gps_lon"} {
		wv, wok := want[field].(float64)
		if !wok {
			continue
		}
		g, gok := qaImgNum(ns, field)
		if !gok {
			t.Errorf("QA AC-1: %q %s absent, oracle wants %v", rel, field, wv)
			continue
		}
		if field == "gps_lat" || field == "gps_lon" {
			if qaImgAbs(g-wv) > 0.01 {
				t.Errorf("QA AC-1: %q %s = %v, oracle wants ~%v", rel, field, g, wv)
			}
		} else if g != wv {
			t.Errorf("QA AC-1: %q %s = %v, oracle wants %v", rel, field, g, wv)
		}
	}
	for _, field := range []string{"format", "make", "model"} {
		wv := want[field].(string)
		gs := asyncStr(ns, field)
		if gs != wv {
			t.Errorf("QA AC-1: %q %s = %q, oracle wants %q", rel, field, gs, wv)
		}
	}
	// The date normalization is the load-bearing mapping: oracle computes RFC3339
	// independently and the enricher must match exactly.
	if got := asyncStr(ns, "date_taken"); got != qaImgDTRFC3339 {
		t.Errorf("QA AC-1: %q date_taken = %q, want normalized %q (DateTimeOriginal %q)", rel, got, qaImgDTRFC3339, qaImgDT)
	}
	// Core-stamped provenance + a ready stage for the EXIF-bearing field.
	if p := doc.Provenance["width"]; p == nil || asyncStr(p, "plugin_id") != "image-enricher" {
		t.Errorf("QA AC-1: %q _provenance.width missing or not image-enricher: %v", rel, p)
	}
	if !asyncStageHas(doc.Stages, "image-enricher", "ok") {
		t.Errorf("QA AC-1: %q no _stages {image-enricher, ok}: %v", rel, doc.Stages)
	}
}

// qaAssertHEIC asserts the DIFFERENT-named HEIC fixture (exiftool supplies full
// HEIC data; stdlib discovery soft-fails). Skips if sips could not produce HEIC.
func qaAssertHEIC(t *testing.T, byRel map[string]itemDTO, fx qaImgFixtures) {
	t.Helper()
	if fx.heicRel == "" {
		t.Skip("HEIC fixture not generated (sips unavailable) — HEIC edge skipped; oracle/Cyrillic/soft-fail re-derivation stands")
	}
	it, ok := byRel[fx.heicRel]
	if !ok {
		t.Fatalf("QA AC-image: %q not discovered; have %v", fx.heicRel, pathsOf(byRel))
	}
	if it.Status != "ready" {
		t.Errorf("QA AC-image: %q status = %q, want ready", fx.heicRel, it.Status)
	}
	ns := parseAsyncDoc(t, it.Document).Sources["image-enricher"]
	if w, _ := qaImgNum(ns, "width"); w <= 0 {
		t.Errorf("QA AC-image: %q sources.image-enricher.width = %v, want >0 (exiftool supplies full HEIC data)", fx.heicRel, ns["width"])
	}
}

