// qaAssertNamespaceIsolation asserts sources has the image-enricher namespace and
// NO other source namespace (image module binds only image-enricher), and that the
// core-stamped _provenance/_view/_stages are present (Merge never touched them).
func qaAssertNamespaceIsolation(t *testing.T, byRel map[string]itemDTO) {
	t.Helper()
	it, ok := byRel["DSC_5082.jpg"]
	if !ok {
		t.Fatalf("QA AC-1: DSC_5082.jpg not persisted; have %v", pathsOf(byRel))
	}
	doc := parseAsyncDoc(t, it.Document)
	if _, ok := doc.Sources["image-enricher"]; !ok {
		t.Fatalf("QA AC-1: sources.image-enricher missing: %v", doc.Sources)
	}
	for ns := range doc.Sources {
		if ns != "image-enricher" {
			t.Errorf("QA AC-1: stray source namespace %q (image module must bind only image-enricher)", ns)
		}
	}
	if len(doc.Provenance) == 0 || len(doc.View) == 0 || len(doc.Stages) == 0 {
		t.Errorf("QA AC-1: core-stamped provenance/view/stages incomplete: prov=%d view=%d stages=%d",
			len(doc.Provenance), len(doc.View), len(doc.Stages))
	}
}

// qaAssertIdempotentRescan asserts re-scanning the same library leaves items ready
// (no regression to pending/stale) and does not duplicate items (PutItem upserts
// by file_id). This is the AC-1/AC-queue idempotency property for the image path.
func qaAssertIdempotentRescan(t *testing.T, client *http.Client, baseURL string, libID int64, before map[string]itemDTO) {
	t.Helper()
	second := scanLibrary(t, client, baseURL, qaImgToken, libID)
	after := indexByPath(t, listItems(t, client, baseURL, qaImgToken, libID))
	if len(after) != len(before) {
		t.Fatalf("QA AC-1: re-scan changed item count %d -> %d (expected idempotent upsert)", len(before), len(after))
	}
	if second.Persisted != len(before) {
		t.Errorf("QA AC-1: re-scan persisted=%d, want %d (idempotent)", second.Persisted, len(before))
	}
	for rel, it := range after {
		if it.Status != "ready" {
			t.Errorf("QA AC-1: after re-scan %q status = %q, want ready (no stale regression)", rel, it.Status)
		}
	}
}
